import React, { useState } from "react";
import Modal from "./components/modal/Modal";
import Card from "./components/card/Card";
import Input from "./components/input/Input";
import TodoItem from "./components/todo-item/TodoItem";
import TextArea from "./components/input/TextArea";
import Button from "./components/button/Button";
import "./App.css";

const TODOS_MOCK = [
  {
    id: "1",
    title: "Todo 1",
    description:
      "Lorem ipsum dolor sit amet consectetur adipisicing elit. At id illo repellendus non maiores in pariatur aliquam iure fugit amet!",
    completed: false,
  },
  {
    id: "2",
    title: "Todo 2",
    description: "Lorem ipsum dolor sit amet consectetur adipisicing elit!",
    completed: false,
  },
  {
    id: "3",
    title: "Todo 3",
    description: "Lorem ipsum dolor sit amet consectetur adipisicing elit!",
    completed: true,
  },
  {
    id: "4",
    title: "Todo 4",
    description: "Lorem ipsum dolor sit amet consectetur adipisicing elit!",
    completed: true,
  },
];

function App() {
  const [todos, setTodos] = useState(TODOS_MOCK);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTodo, setEditingTodo] = useState(null);

  const handleAddTodo = (title, description) => {
    const newTodo = {
      id: Date.now().toString(),
      title,
      description,
      completed: false,
    };

    setTodos([...todos, newTodo]);
    setIsModalOpen(false);
  };

  const handleUpdateTodo = (id, title, description) => {
    setTodos(
      todos.map((t) =>
        t.id === id ? { ...t, title, description } : t
      )
    );
    setIsModalOpen(false);
  };

  const handleDelete = (id) => {
    setTodos(todos.filter((t) => t.id !== id));
  };

  const toggleCompleted = (id) => {
    setTodos(
      todos.map((t) =>
        t.id === id ? { ...t, completed: !t.completed } : t
      )
    );
  };

  const openAddModal = () => {
    setEditingTodo(null);
    setIsModalOpen(true);
  };

  const openEditModal = (todo) => {
    setEditingTodo(todo);
    setIsModalOpen(true);
  };

  const activeTodos = todos.filter((t) => !t.completed);
  const completedTodos = todos.filter((t) => t.completed);

  return (
    <div className="App">
      <div className="app-container">
        <Card>
          <h2>Create Todo</h2>
          <form>
            <Input placeholder="Title" type="text" disabled />
            <TextArea placeholder="Description" disabled />
            <Button disabled>Create</Button>
          </form>
          <p style={{ fontSize: "12px", opacity: 0.7 }}>
            Formularul real este în modal. Apasă „Add +”.
          </p>
        </Card>

        <Card>
          <h1>My todos</h1>
          <Button onClick={openAddModal}>Add +</Button>

          <div className="list-container">
            {activeTodos.map((todo) => (
              <TodoItem
                key={todo.id}
                {...todo}
                onToggle={() => toggleCompleted(todo.id)}
                onDelete={() => handleDelete(todo.id)}
                onEdit={() => openEditModal(todo)}
              />
            ))}
          </div>

          <div className="separator"></div>

          <h2>Completed</h2>
          <div className="list-container">
            {completedTodos.map((todo) => (
              <TodoItem
                key={todo.id}
                {...todo}
                onToggle={() => toggleCompleted(todo.id)}
                onDelete={() => handleDelete(todo.id)}
                onEdit={() => openEditModal(todo)}
              />
            ))}
          </div>
        </Card>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}>
        <AddTodoForm
          onAdd={handleAddTodo}
          onUpdate={handleUpdateTodo}
          editingTodo={editingTodo}
        />
      </Modal>
    </div>
  );
}

export default App;
